using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using Microsoft.AspNetCore.Components.Web;
using Microsoft.CodeAnalysis;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00018 : MinimalApiTestBase
    {
        [TestMethod]
        public void Each_Minimal_Api_Mapping_Must_Use_WithName_And_The_OperationIds_Must_Contains_Current_Version()
        {
            var invalidEndpointMappings = (from mapStatement in MapStatements
                                           let version = Regex.Match(mapStatement.SyntaxTree, @"\.MapToApiVersion\((?<version>\d+)\)")
                                           let match = Regex.Match(mapStatement.SyntaxTree, @"\.WithName\(""(?<name>[^""]+)""\)")
                                           where match.Success &&
                                                 version.Success && 
                                                 match.Value.Contains($"V{version.Groups["version"].Value.ToIntOrDefault()}", StringComparison.OrdinalIgnoreCase).IsFalse()
                                           select new
                                           {
                                               Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FilePath:  {mapStatement.FilePath}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Syntax:    

{mapStatement.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{mapStatement.SyntaxTree.Replace(match.Value, $"WithName(\"{match.Groups["name"].Value}V{version.Groups["version"].Value}\")").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(invalidEndpointMappings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00018

When using .WithName(...) this represents an operation id of the open api specification. 
This operation id have to be unique over all versions. Which means if you have 2 versions with
for example named GetAllPersons you will got an error. To keep it working add a postfix with the
version then the name is unique.

Findings {invalidEndpointMappings.Count}': 

{invalidEndpointMappings.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
